Certainly! There are many sorting algorithms to choose from, each with its own efficiency characteristics and use cases. One of the most efficient and widely used sorting algorithms is the Heap Sort. In Heap Sort, we use a binary heap data structure. Here is a Python implementation of Heap Sort:

```python
class MaxHeap:
    def __init__(self, items=[]):
        self.heap = [0]
        for item in items:
            self.heap.append(item)
            self.__floatUp(len(self.heap) - 1)

    def insert(self, key):
        self.heap.append(key)
        self.__floatUp(len(self.heap) - 1)

    def __floatUp(self, index):
        parent = index // 2

        # If the current node is larger than its parent, swap them and continue swapping up
        if index <= 1:
            return
        elif self.heap[index] > self.heap[parent]:
            self.__swap(index, parent)
            self.__floatUp(parent)

    def __swap(self, index1, index2):
        self.heap[index1], self.heap[index2] = self.heap[index2], self.heap[index1]

    def extractMax(self):
        if len(self.heap) > 2:
            self.__swap(1, len(self.heap) - 1) # swap root to the last element
            max = self.heap.pop() # remove the last element
            self.__bubbleDown(1) # restore the heap property
        elif len(self.heap) == 2:
            max = self.heap.pop() # remove the last element
        else:
            max = None
        return max

    def __bubbleDown(self, index):
        left = index * 2
        right = index * 2 + 1
        largest = index

        if len(self.heap) > left and self.heap[largest] < self.heap[left]:
            largest = left

        if len(self.heap) > right and self.heap[largest] < self.heap[right]:
            largest = right

        if largest != index:
            self.__swap(index, largest)
            self.__bubbleDown(largest)

    def getMaximum(self):
        return self.heap[1]

    def decreaseKey(self, index, key):
        self.heap[index] = key
        while index > 1 and self.heap[index // 2] < self.heap[index]:
            self.__swap(index, index // 2)
            index = index // 2

    def delete(self, index):
        self.decreaseKey(index, -float('inf'))
        self.extractMax()

    def getHeap(self):
        return self.heap

def heapSort(arr):
    h = MaxHeap(arr)
    sorted_arr = []
    while len(h.heap) > 1:
        sorted_arr.append(h.extractMax())
    return sorted_arr

# Example usage
arr = [12, 11, 13, 5, 6, 7]
sorted_arr = heapSort(arr)
print("Sorted array is:", sorted_arr)
```

